result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/jredact.py", "content": "#!/usr/bin/env python3
"""jredact - structured-document redactor for JSON.

Applies redaction rules (path patterns) to a JSON document.

Path pattern syntax (strict, anything else fails closed):
    name      matches the key `name` in an object
    *         matches any single key at this level
    [*]       matches any index of an array at this level
    name[*]   shorthand: key `name`, then any array index
    Segments are joined with `.`:  parties[*].ssn, payments[*].account.number, *.email

Semantics:
    - A matched value that is a string is replaced by [REDACTED].
    - A matched value that is NOT a string (number, bool, null,
      object, array) is a fail-closed condition: exit 3, no output.
      Silent partial redaction is worse than none.
    - Unknown path syntax in the rules file also fails closed (exit 2).
    - Paths that do not resolve in the document are fine and skipped.

Usage:
    jredact.py RULES.yaml INPUT.json            # redacted JSON on stdout

Exit codes:
    0  success
    2  startup/validation error (unreadable files, bad YAML, bad path syntax)
    3  fail-closed: a rule matched a non-string value
"""

from __future__ import annotations

import json
import re
import sys

REDACTED = "[REDACTED]"

EXIT_OK = 0
EXIT_STARTUP = 2
EXIT_NON_STRING = 3

NAME_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_-]*$")
INDEX_ANY = object()  # sentinel for [*]
STAR = object()       # sentinel for *


class StartupError(Exception):
    """Bad rules or bad input at startup -> exit 2."""


class NonStringMatch(Exception):
    """A rule resolved to a non-string value -> exit 3."""


def compile_path(pattern: str) -> list:
    """Compile a path pattern into segments. Fail closed on unknown syntax."""
    if not isinstance(pattern, str) or not pattern.strip():
        raise StartupError(f"empty or non-string path pattern: {pattern!r}")
    pattern = pattern.strip()
    segs: list = []
    for raw in pattern.split("."):
        token = raw.strip()
        if not token:
            raise StartupError(f"empty segment in path {pattern!r}")
        # optional trailing [*]
        m = re.fullmatch(r"(.+?)\[\*\]", token)
        if m:
            base, token = m.group(1), None
        else:
            base, token = token, None
        if base == "*":
            segs.append(STAR)
        elif NAME_RE.fullmatch(base):
            segs.append(base)
        else:
            raise StartupError(f"unknown path syntax near {base!r} in {pattern!r}")
        if token is not None:  # the trailing [*]
            segs.append(INDEX_ANY)
        if len(segs) > 64:
            raise StartupError(f"path too deep: {pattern!r}")
    return segs


def load_rules(path: str) -> list[list]:
    """Load rules.yaml. Accepts a top-level list of patterns or {rules: [...]}."""
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = __import__("yaml").safe_load(f)
    except OSError as e:
        raise StartupError(f"cannot read rules file {path}: {e}") from e
    except Exception as e:  # yaml.YAMLError and friends
        raise StartupError(f"invalid YAML in {path}: {e}") from e

    if isinstance(data, dict):
        if "rules" not in data:
            raise StartupError("rules file must be a list of patterns or have a 'rules' key")
        data = data["rules"]
    if not isinstance(data, list):
        raise StartupError("rules must be a list of path patterns")

    return [compile_path(p) for p in data]


def iter_matches(node, segs: list):
    """Yield every value in `node` that the compiled path `segs` resolves to."""
    if not segs:
        yield node
        return
    seg, rest = segs[0], segs[1:]
    if seg is INDEX_ANY:
        if isinstance(node, list):
            for item in node:
                yield from iter_matches(item, rest)
    elif seg is STAR:
        if isinstance(node, dict):
            for v in node.values():
                yield from iter_matches(v, rest)
    else:  # literal key
        if isinstance(node, dict) and seg in node:
            yield from iter_matches(node[seg], rest)


def redact(doc, compiled_rules: list[list]):
    """Return a deep-redacted copy of doc. Raise NonStringMatch on fail-closed."""
    # Pass 1: verify every match is a string BEFORE producing anything.
    for segs in compiled_rules:
        for value in iter_matches(doc, segs):
            if not isinstance(value, str):
                raise NonStringMatch(
                    f"rule path resolved to non-string value of type "
                    f"{type(value).__name__}: {value!r}"
                )
    # Pass 2: rebuild with redactions.
    def walk(node):
        if isinstance(node, dict):
            out = {}
            for k, v in node.items():
                hit = False
                for segs in compiled_rules:
                    if len(segs) == 1 and segs[0] is not STAR and segs[0] is not INDEX_ANY \
                            and segs[0] == k:
                        hit = True
                        break
                if hit and isinstance(v, str):
                    out[k] = REDACTED
                else:
                    sub = walk(v)
                    # single-segment STAR rules match every child value
                    for segs in compiled_rules:
                        if len(segs) == 1 and segs[0] is STAR and isinstance(v, str):
                            sub = REDACTED
                            break
                    out[k] = sub
            return out
        if isinstance(node, list):
            return [walk(item) for item in node]
        return node
    return _redact_top(doc, compiled_rules)


def _redact_top(doc, compiled_rules):
    """Full recursive redaction handling multi-segment paths correctly."""
    memo_rules = compiled_rules

    def matches_here(segs_list):
        return [segs[1:] for segs in segs_list if len(segs) >= 1]

    def walk(node, active):
        # active: list of remaining-segment lists whose next segment applies here
        if isinstance(node, dict):
            # which rules terminate exactly here (matched a string child)?
            terminal_str_keys = set()
            for segs in active:
                if len(segs) == 1:
                    seg = segs[0]
                    if seg is STAR:
                        for k, v in node.items():
                            if isinstance(v, str):
                                terminal_str_keys.add(k)
                    elif seg is not INDEX_ANY and seg in node \
                            and isinstance(node[seg], str):
                        terminal_str_keys.add(seg)
            out = {}
            for k, v in node.items():
                if k in terminal_str_keys:
                    out[k] = REDACTED
                    continue
                nxt = []
                for segs in active:
                    if not segs:
                        continue
                    seg = segs[0]
                    if seg is STAR:
                        nxt.extend([s[1:] for s in [segs]])
                    elif seg is not INDEX_ANY and seg == k:
                        nxt.append(segs[1:])
                out[k] = walk(v, nxt) if nxt else v
            return out
        if isinstance(node, list):
            nxt = []
            for segs in active:
                if segs and segs[0] is INDEX_ANY:
                    nxt.append(segs[1:])
            if not nxt:
                return node
            return [walk(item, nxt) for item in node]
        return node

    return walk(doc, memo_rules)


def rescan_violations(doc, compiled_rules: list[list]) -> list[str]:
    """Re-scan guarantee: report any rule path still resolving to an unredacted string."""
    bad = []
    for segs in compiled_rules:
        for value in iter_matches(doc, segs):
            if isinstance(value, str) and value != REDACTED:
                bad.append(value)
    return bad


def run(rules_path: str, input_path: str) -> int:
    import yaml  # local import so --help works without pyyaml

    compiled = load_rules(rules_path)

    try:
        with open(input_path, "r", encoding="utf-8") as f:
            doc = json.load(f)
    except OSError as e:
        raise StartupError(f"cannot read input file {input_path}: {e}") from e
    except json.JSONDecodeError as e:
        raise StartupError(f"invalid JSON in {input_path}: {e}") from e

    try:
        result = redact(doc, compiled)
    except NonStringMatch:
        return EXIT_NON_STRING

    violations = rescan_violations(result, compiled)
    if violations:  # defensive; should be impossible
        print(f"internal re-scan failure: {violations}", file=sys.stderr)
        return EXIT_NON_STRING

    json.dump(result, sys.stdout, indent=2, ensure_ascii=False)
    sys.stdout.write("\n")
    return EXIT_OK


def main(argv: list[str]) -> int:
    if len(argv) != 3 or argv[1] in ("-h", "--help"):
        print(__doc__.strip(), file=sys.stderr if len(argv) != 3 else sys.stdout)
        return EXIT_OK if len(argv) == 2 else EXIT_STARTUP
    try:
        return run(argv[1], argv[2])
    except StartupError as e:
        print(f"jredact: startup validation failed: {e}", file=sys.stderr)
        return EXIT_STARTUP


if __name__ == "__main__":
    sys.exit(main(sys.argv))
"})
